public class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email'
                     description='Finds an existing Contact by email address (case-insensitive).')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        // Collect unique, non-blank, trimmed emails for the query
        Set<String> uniqueEmails = new Set<String>();
        for (Request req : requests) {
            if (req.email != null) {
                String trimmed = req.email.trim();
                if (!trimmed.isEmpty()) {
                    uniqueEmails.add(trimmed);
                }
            }
        }

        // Single SOQL query – respects sharing by default
        // Email field is case-insensitive in Salesforce, so IN handles case matching
        Map<String, Contact> earliestByEmail = new Map<String, Contact>();
        if (!uniqueEmails.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :uniqueEmails
                ORDER BY CreatedDate ASC
            ];

            // First encounter per email (lowercased) is the earliest CreatedDate
            for (Contact c : contacts) {
                String key = c.Email.toLowerCase();
                if (!earliestByEmail.containsKey(key)) {
                    earliestByEmail.put(key, c);
                }
            }
        }

        // Build one Result per Request, preserving order
        for (Request req : requests) {
            Result r = new Result();
            String lookupKey = '';
            if (req.email != null) {
                lookupKey = req.email.trim().toLowerCase();
            }

            if (!lookupKey.isEmpty() && earliestByEmail.containsKey(lookupKey)) {
                r.found = true;
                r.contactId = earliestByEmail.get(lookupKey).Id;
            } else {
                r.found = false;
                r.contactId = null;
            }

            results.add(r);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(label='Email' required=true
                           description='The email address to search for (case-insensitive).')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID'
                           description='The Id of the matched Contact, or null if not found.')
        public Id contactId;

        @InvocableVariable(label='Found'
                           description='True if a Contact was found, false otherwise.')
        public Boolean found;
    }
}
