public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Request body is not valid JSON.');
        }

        if (!(parsed instanceof Map)) {
            throw new PayloadException('Request body is not a JSON object.');
        }

        try {
            return doParse((Map<String, Object>) parsed);
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Invalid payload: ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => order.lines.size(),
            'total' => order.total
        };
        return JSON.serialize(ack);
    }

    private static Order doParse(Map<String, Object> map) {
        // Validate and extract order number
        Object numObj = map.get('number');
        if (numObj == null) {
            throw new PayloadException('Order number is missing.');
        }
        String number = String.valueOf(numObj);
        if (String.isBlank(number)) {
            throw new PayloadException('Order number is blank.');
        }

        Order order = new Order();
        order.orderNumber = number;

        // Date (optional)
        if (map.get('date') != null) {
            order.orderDate = Date.valueOf(String.valueOf(map.get('date')));
        }

        // Currency (optional)
        if (map.get('currency') != null) {
            order.currencyCode = String.valueOf(map.get('currency'));
        }

        // Customer (optional)
        if (map.get('customer') != null && map.get('customer') instanceof Map) {
            Map<String, Object> customerMap = (Map<String, Object>) map.get('customer');
            if (customerMap.get('email') != null) {
                order.customerEmail = String.valueOf(customerMap.get('email'));
            }
        }

        // Lines
        order.lines = new List<Line>();
        Decimal total = 0;

        if (map.get('lines') != null && map.get('lines') instanceof List) {
            List<Object> linesList = (List<Object>) map.get('lines');
            for (Object lineObj : linesList) {
                if (!(lineObj instanceof Map)) {
                    throw new PayloadException('Each line must be a JSON object.');
                }
                Line line = parseLine((Map<String, Object>) lineObj);
                order.lines.add(line);
                total += line.lineTotal;
            }
        }

        order.total = total;
        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        // SKU
        Object skuObj = lineMap.get('sku');
        if (skuObj == null) {
            throw new PayloadException('Line is missing sku.');
        }
        line.sku = String.valueOf(skuObj);
        if (String.isBlank(line.sku)) {
            throw new PayloadException('Line sku is blank.');
        }

        // Quantity
        Object qtyObj = lineMap.get('quantity');
        if (qtyObj == null) {
            throw new PayloadException('Line is missing quantity.');
        }
        Integer quantity;
        if (qtyObj instanceof Integer) {
            quantity = (Integer) qtyObj;
        } else if (qtyObj instanceof Long) {
            quantity = (Integer) qtyObj;
        } else if (qtyObj instanceof Double) {
            quantity = (Integer) Math.floor((Double) qtyObj);
        } else {
            quantity = Integer.valueOf(String.valueOf(qtyObj));
        }
        if (quantity <= 0) {
            throw new PayloadException('Line quantity must be positive.');
        }
        line.quantity = quantity;

        // Unit price
        Object priceObj = lineMap.get('unitPrice');
        if (priceObj == null) {
            throw new PayloadException('Line is missing unitPrice.');
        }
        Decimal unitPrice = toDecimal(priceObj);
        if (unitPrice < 0) {
            throw new PayloadException('Line unitPrice must not be negative.');
        }
        line.unitPrice = unitPrice;

        // Discount (defaults to 0)
        Decimal discount = 0;
        Object discObj = lineMap.get('discount');
        if (discObj != null) {
            discount = toDecimal(discObj);
        }
        line.discount = discount;

        // Compute line total: quantity * unitPrice * (1 - discount), rounded half-up to 2 dp
        line.lineTotal = round2(quantity * unitPrice * (1 - discount));

        return line;
    }

    /**
     * Converts a JSON-deserialized number to Decimal.
     * Uses String.valueOf for Doubles to preserve the intended decimal literal
     * (avoids binary floating-point representation issues).
     */
    private static Decimal toDecimal(Object obj) {
        if (obj == null) {
            return 0;
        }
        if (obj instanceof Integer) {
            return Decimal.valueOf((Integer) obj);
        }
        if (obj instanceof Long) {
            return Decimal.valueOf((Long) obj);
        }
        if (obj instanceof Double) {
            return Decimal.valueOf(String.valueOf((Double) obj));
        }
        return Decimal.valueOf(String.valueOf(obj));
    }

    /**
     * Rounds a Decimal to 2 decimal places using half-up rounding.
     * 1.005 → 1.01, 1.004 → 1.00
     */
    private static Decimal round2(Decimal value) {
        // value * 100 is exact Decimal arithmetic; add 0.5 then floor
        Double d = Double.valueOf(value * 100 + 0.5);
        Double floored = Math.floor(d);
        return (Decimal) floored / 100;
    }
}
