public class LogPurgeJob implements Schedulable {

    public void execute(SchedulableContext ctx) {
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date oneEightyDaysAgo = Date.today().addDays(-180);

        List<FB_Integration_Log__c> toDelete = new List<FB_Integration_Log__c>();

        // Delete non-ERROR logs older than 30 days
        for (FB_Integration_Log__c log : [
            SELECT Id FROM FB_Integration_Log__c
            WHERE CreatedDate < :thirtyDaysAgo
            AND (Level__c = NULL OR Level__c != 'ERROR')
        ]) {
            toDelete.add(log);
        }

        // Delete ERROR logs older than 180 days
        for (FB_Integration_Log__c log : [
            SELECT Id FROM FB_Integration_Log__c
            WHERE CreatedDate < :oneEightyDaysAgo
            AND Level__c = 'ERROR'
        ]) {
            toDelete.add(log);
        }

        if (!toDelete.isEmpty()) {
            Database.delete(toDelete, false);
        }
    }

