public class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Seed every requested account with 0 so the contract is guaranteed
        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        // Single aggregate query; respects the running user's sharing by default
        List<AggregateResult> aggregates = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND CloseDate = THIS_YEAR
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ];

        // Overwrite with actual sums; if SUM is null (all Amounts blank) keep 0
        for (AggregateResult ar : aggregates) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal sum = (Decimal) ar.get('totalAmount');
            if (sum != null) {
                result.put(accountId, sum);
            }
        }

        return result;
    }
}
