@IsTest
private class OpportunityForecastServiceTest {

    private static fflib_ApexMocks mocks;
    private static fflib_IDGenerator idGen;
    private static IOpportunitiesSelector mockSelector;

    private static void setupMocks() {
        mocks = new fflib_ApexMocks();
        idGen = new fflib_IDGenerator();
        mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, mockSelector);
    }

    @IsTest
    static void sumsWeightedAmountPerStage() {
        setupMocks();

        Id accountId = idGen.newId('Account');
        Set<Id> accountIds = new Set<Id>{ accountId };

        Opportunity opp1 = new Opportunity(
            Id        = idGen.newId('Opportunity'),
            AccountId = accountId,
            StageName = 'Prospecting',
            Amount    = 10000,
            Probability = 50
        );

        Opportunity opp2 = new Opportunity(
            Id        = idGen.newId('Opportunity'),
            AccountId = accountId,
            StageName = 'Prospecting',
            Amount    = 20000,
            Probability = 25
        );

        Opportunity opp3 = new Opportunity(
            Id        = idGen.newId('Opportunity'),
            AccountId = accountId,
            StageName = 'Negotiation',
            Amount    = 5000,
            Probability = 100
        );

        List<Opportunity> opps = new List<Opportunity>{ opp1, opp2, opp3 };
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opps);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        // opp1: 10000 * 50 / 100 = 5000.00
        // opp2: 20000 * 25 / 100 = 5000.00
        // opp3:  5000 * 100 / 100 = 5000.00
        System.assertEquals(2, result.size(), 'Expected two stages in result');
        System.assertEquals(10000.00, result.get('Prospecting'), 'Prospecting total incorrect');
        System.assertEquals(5000.00, result.get('Negotiation'), 'Negotiation total incorrect');
    }

    @IsTest
    static void roundsEachOpportunityToTwoDecimalsBeforeSumming() {
        setupMocks();

        Id accountId = idGen.newId('Account');
        Set<Id> accountIds = new Set<Id>{ accountId };

        // 123.45 * 33 / 100 = 40.7385 → rounds to 40.74 per opportunity
        Opportunity opp1 = new Opportunity(
            Id        = idGen.newId('Opportunity'),
            AccountId = accountId,
            StageName = 'Qualification',
            Amount    = 123.45,
            Probability = 33
        );

        Opportunity opp2 = new Opportunity(
            Id        = idGen.newId('Opportunity'),
            AccountId = accountId,
            StageName = 'Qualification',
            Amount    = 123.45,
            Probability = 33
        );

        List<Opportunity> opps = new List<Opportunity>{ opp1, opp2 };
        mocks.when(mockSelector.selectOpenByAccountIds(accountIds)).thenReturn(opps);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        // Each opportunity rounds to 40.74, sum = 81.48
        // (If we summed first then rounded: 81.477 → 81.48, same here,
        //  but the per-opportunity rounding is what we're pinning down)
        System.assertEquals(81.48, result.get('Qualification'), 'Per-opportunity rounding not applied');
    }

