        mock.verify(mockUow.registerDirty(futureDate), fflib_ApexMocks.VerifyMode.NEVER());
        mock.verify(mockUow.registerDirty(onCutoff), fflib_ApexMocks.VerifyMode.NEVER());
        mock.verify(mockUow.registerDirty(nullDate), fflib_ApexMocks.VerifyMode.NEVER());
        mock.verify(mockUow.commitWork(), fflib_ApexMocks.VerifyMode.EXACTLY(1));
    }

