    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        fflib_QueryFactory queryFactory = getQueryFactory();
        fflib_QueryBuilder query = queryFactory.create();
        query.from('Opportunity');
        query.addSelect('Account.Name');
        query.where('IsClosed = false');
        query.where('AccountId IN :accountIds');
        query.orderBy('Amount DESC NULLS LAST, CloseDate ASC');
        query.limit(maxRecords);
