public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
        fields.addAll(getFieldSetFields('Credit_Review'));
        return fields;
    }

    public fflib_DataAccess getDataAccess() {
        return fflib_DataAccess.USER_MODE;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        ContactsSelector cs = new ContactsSelector();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField f : cs.getSObjectFieldList()) {
            contactFieldNames.add(f.getDescribe().getName());
        }
        String contactFieldList = String.join(contactFieldNames, ', ');

        List<String> baseFieldNames = new List<String>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            baseFieldNames.add(f.getDescribe().getName());
        }
        String baseFieldList = String.join(baseFieldNames, ', ');

        String soql = 'SELECT ' + baseFieldList + ', (SELECT ' + contactFieldList
            + ' FROM Contacts) FROM Account WITH USER_MODE WHERE Id IN :accountIds';

        List<SObject> results = Database.query(soql);
        return (List<Account>) results;
    }

    private List<Schema.SObjectField> getFieldSetFields(String fieldSetName) {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>();
        Map<String, Schema.FieldSetDescribeResult> fieldSets =
            Account.SObjectType.getDescribe().getFieldSets();
        Schema.FieldSetDescribeResult fs = fieldSets.get(fieldSetName);
        if (fs != null) {
            for (Schema.FieldSetMemberDescribeResult member : fs.getMembers()) {
                fields.add(Account.SObjectType.getFields().get(member.getFieldName()));
            }
        }
        return fields;
    }
}
